"""Site-level summary report."""
import csv

FIELDS = ["site", "sensors", "readings", "mean_value", "max_value"]


def build_site_summary(records):
    """Aggregate sensor records into one row per site.

    Only sensors with status "ok" are counted and null readings are skipped.
    Rows are sorted by site name.
    """
    sites = {}
    for rec in records:
        if rec.get("status") != "ok":
            continue
        entry = sites.setdefault(rec["site"], {"sensors": 0, "values": []})
        entry["sensors"] += 1
        for reading in rec.get("readings", []):
            value = reading.get("value")
            if value is not None:
                entry["values"].append(float(value))
    rows = []
    for site in sorted(sites):
        values = sites[site]["values"]
        if not values:
            continue
        rows.append({
            "site": site,
            "sensors": sites[site]["sensors"],
            "readings": len(values),
            "mean_value": sum(values) / len(values),
            "max_value": max(values),
        })
    return rows


def write_csv(rows, path):
    with open(path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(FIELDS)
        for r in rows:
            w.writerow([r["site"], r["sensors"], r["readings"],
                        f"{r['mean_value']:.2f}", f"{r['max_value']:.2f}"])
EOF
